"use client";

import { useEffect, useState } from "react";
import { useAuth } from "../context/AuthContext";
import { useRouter } from "next/navigation";
import { db } from "../../lib/firebase";
import { collection, getDocs, query, where, orderBy } from "firebase/firestore"; // <--- Added query tools
import { MapPin, Package, LogOut, Receipt } from "lucide-react";

export default function ProfilePage() {
  const { user, logout } = useAuth();
  const router = useRouter();
  
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) { router.push("/"); } 
    else { fetchOrders(); }
  }, [user]);

  const fetchOrders = async () => {
    if (!user) return;
    
    try {
      // Correct Logic: Fetch from root 'orders' where userId == current user
      const q = query(
        collection(db, "orders"),
        where("userId", "==", user.uid),
        orderBy("createdAt", "desc") // Show newest first
      );

      const querySnapshot = await getDocs(q);
      const userOrders = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setOrders(userOrders);
    } catch (error) {
      console.error("Error fetching orders:", error);
    } finally {
      setLoading(false);
    }
  };

  if (!user) return null;

  return (
    <div className="min-h-screen bg-slate-50 py-12">
      <div className="container mx-auto px-4 max-w-5xl">
        
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
            <h1 className="text-3xl font-black text-slate-900">My Profile</h1>
            <button 
              onClick={() => { logout(); router.push("/"); }} 
              className="text-red-600 font-bold hover:bg-red-50 px-6 py-2 rounded-full border border-transparent hover:border-red-100 transition-all flex items-center gap-2"
            >
              <LogOut className="w-4 h-4" /> Logout
            </button>
        </div>

        <div className="grid md:grid-cols-3 gap-8">
            
            {/* 1. USER CARD */}
            <div className="space-y-6">
                <div className="bg-white p-8 rounded-[2rem] text-center shadow-sm border border-slate-100">
                    <div className="relative w-24 h-24 mx-auto mb-4">
                      <img 
                        src={user.photoURL || "/default.png"} 
                        className="w-full h-full rounded-full object-cover border-4 border-orange-50" 
                        alt="Profile"
                      />
                      <div className="absolute bottom-0 right-0 bg-green-500 w-6 h-6 rounded-full border-4 border-white"></div>
                    </div>
                    <h2 className="text-xl font-bold text-slate-900">{user.displayName}</h2>
                    <p className="text-slate-400 text-sm font-medium">{user.email}</p>
                </div>

                <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                    <h3 className="font-bold text-slate-900 mb-4 flex items-center gap-2">
                      <MapPin className="w-5 h-5 text-orange-600"/> Saved Addresses
                    </h3>
                    <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
                       <span className="text-xs font-bold text-orange-600 uppercase mb-1 block">Home</span>
                       <p className="text-slate-700 text-sm font-medium leading-relaxed">
                         Room 402, Boys Hostel, MMMUT Campus, Gorakhpur
                       </p>
                    </div>
                </div>
            </div>

            {/* 2. ORDER HISTORY */}
            <div className="md:col-span-2 bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 min-h-[500px]">
                <h3 className="font-black text-2xl text-slate-900 mb-8 flex items-center gap-3">
                  <Package className="w-7 h-7 text-slate-900"/> Order History
                </h3>
                
                {loading ? (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400 gap-2">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600"></div>
                    Loading orders...
                  </div>
                ) : orders.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-64 text-center border-2 border-dashed border-slate-100 rounded-3xl">
                     <Receipt className="w-12 h-12 text-slate-200 mb-2"/>
                     <p className="text-slate-400 font-medium">No orders found.</p>
                     <button onClick={() => router.push("/")} className="mt-4 text-orange-600 font-bold hover:underline">Start Ordering</button>
                  </div>
                ) : (
                  <div className="space-y-4">
                      {orders.map((order) => (
                          <div key={order.id} className="group border border-slate-100 rounded-3xl p-5 hover:border-orange-200 hover:shadow-lg transition-all duration-300">
                              <div className="flex justify-between items-start mb-3">
                                  <div>
                                    <h4 className="font-bold text-lg text-slate-900 group-hover:text-orange-600 transition-colors">
                                      {order.restaurant}
                                    </h4>
                                    <p className="text-xs text-slate-400 font-medium mt-1">{order.date} • ID: {order.id.slice(0,6)}</p>
                                  </div>
                                  <div className="text-right">
                                    <span className="block font-black text-lg text-slate-900">₹{order.total}</span>
                                    <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase mt-1 ${
                                      order.status === 'Delivered' ? 'bg-green-100 text-green-700' : 'bg-blue-50 text-blue-600'
                                    }`}>
                                      {order.status}
                                    </span>
                                  </div>
                              </div>
                              
                              <div className="bg-slate-50 rounded-xl p-3">
  <p className="text-slate-600 text-sm font-medium line-clamp-1">
    
    {/* REPLACE THE OLD ONE-LINER WITH THIS SMART LOGIC */}
    {order.items?.map((item: any, index: number) => {
      // Case 1: If it's the old format (just a string like "Burger")
      if (typeof item === 'string') {
        return <span key={index}>{index > 0 ? ", " : ""}1 x {item}</span>;
      }
      
      // Case 2: If it's the new format (Object like {name: "Burger", qty: 2})
      return (
        <span key={index}>
          {index > 0 ? ", " : ""}
          {item.qty || 1} x {item.name}
        </span>
      );
    })}

  </p>
</div>
                          </div>
                      ))}
                  </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
}